const envelope = $input.first().json || {};
const body = envelope.body && typeof envelope.body === 'object' ? envelope.body : {};
const approvalRecord = body.approval_record && typeof body.approval_record === 'object' ? body.approval_record : body.approval_record_template && typeof body.approval_record_template === 'object' ? body.approval_record_template : null;
if (!approvalRecord || Array.isArray(body.contacts) || (body.contact && typeof body.contact === 'object')) return [{ json: envelope }];
return [{ json: { ...envelope, body: { ...body, contact: approvalRecord } } }];

const envelope = $input.first().json || {};
const body = envelope.body && typeof envelope.body === 'object' ? envelope.body : {};
// Safety controls are operator-owned. Incoming requests cannot disable dry-run, raise caps, or select another campaign.
const config = {
  dry_run: true,
  daily_cap: 25,
  campaign_id: 'REPLACE_WITH_INSTANTLY_CAMPAIGN_UUID',
  policy_endpoint_url: 'https://CONFIGURE-ME.invalid/outreach-policy/check',
  audit_endpoint_url: 'https://CONFIGURE-ME.invalid/audit/outreach'
};
const clean = (value, max = 500) => String(value ?? '').trim().replace(/\s+/g, ' ').slice(0, max);
const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const sourceContacts = Array.isArray(body.contacts) ? body.contacts : [body.contact && typeof body.contact === 'object' ? body.contact : body];
const errors = [];
if (sourceContacts.length < 1) errors.push('At least one contact is required');
if (sourceContacts.length > config.daily_cap) errors.push(`Request exceeds the configured daily cap of ${config.daily_cap}`);
const hashKey = (seed) => { let hash = 2166136261; for (let i = 0; i < seed.length; i++) { hash ^= seed.charCodeAt(i); hash = Math.imul(hash, 16777619); } return (hash >>> 0).toString(16).padStart(8, '0'); };
const allowedBases = new Set(['explicit_consent', 'legitimate_interest_documented', 'existing_customer']);
const contacts = sourceContacts.slice(0, config.daily_cap).map((raw, index) => {
  const email = clean(raw?.email, 254).toLowerCase();
  const lawfulBasis = clean(raw?.lawful_basis, 80).toLowerCase();
  const contactErrors = [];
  if (!emailPattern.test(email)) contactErrors.push('valid email required');
  if (raw?.email_verified !== true) contactErrors.push('email_verified must be true');
  if (raw?.approved !== true || clean(raw?.approval_status, 80).toLowerCase() !== 'approved') contactErrors.push('separate human approval is required');
  if (raw?.lawful_basis_documented !== true || !allowedBases.has(lawfulBasis)) contactErrors.push('documented lawful basis is required');
  if (raw?.do_not_contact === true || raw?.unsubscribed === true || raw?.suppressed === true) contactErrors.push('contact is locally suppressed');
  const keySeed = `${email}|${config.campaign_id}`;
  const contactKey = clean(raw?.contact_key, 160) || `ct_${hashKey(email)}`;
  const idempotencyKey = clean(raw?.idempotency_key, 180) || `instantly_${hashKey(keySeed)}`;
  if (contactErrors.length) errors.push(`contacts[${index}]: ${contactErrors.join(', ')}`);
  return {
    email,
    first_name: clean(raw?.first_name, 80),
    last_name: clean(raw?.last_name, 100),
    company_name: clean(raw?.company_name, 160),
    job_title: clean(raw?.job_title, 160),
    website: clean(raw?.website || raw?.company_domain, 240),
    phone: clean(raw?.phone, 40),
    personalization: clean(raw?.personalisation || raw?.personalization, 500),
    contact_key: contactKey,
    idempotency_key: idempotencyKey,
    lawful_basis: lawfulBasis,
    lawful_basis_documented: raw?.lawful_basis_documented === true,
    approved: raw?.approved === true,
    approval_status: clean(raw?.approval_status, 80).toLowerCase()
  };
});
const campaignId = config.campaign_id;
if (!config.dry_run && campaignId.includes('REPLACE_WITH')) errors.push('Configure a real Instantly campaign UUID before live mode');
return [{ json: {
  request_id: clean(body.request_id, 160) || `enrol-${Date.now()}`,
  received_at: new Date().toISOString(),
  valid: errors.length === 0,
  validation_errors: errors,
  campaign_id: campaignId,
  contacts,
  config
} }];

const base = $node['Normalise and Validate Approval'].json;
const response = $input.first().json || {};
const suppressed = new Set((response.suppressed_emails || []).map(v => String(v).trim().toLowerCase()));
const duplicates = new Set((response.duplicate_keys || []).map(v => String(v)));
const enrolledToday = Math.max(0, Number(response.enrolled_today || 0));
const remaining = Math.max(0, base.config.daily_cap - enrolledToday);
const blocked = [];
for (const contact of base.contacts) {
  if (suppressed.has(contact.email)) blocked.push({ contact_key: contact.contact_key, reason: 'suppressed' });
  if (duplicates.has(contact.idempotency_key)) blocked.push({ contact_key: contact.contact_key, reason: 'duplicate' });
}
if (base.contacts.length > remaining) blocked.push({ reason: 'daily_cap', remaining, requested: base.contacts.length });
if (response.allowed !== true) blocked.push({ reason: String(response.reason || 'policy_service_did_not_explicitly_allow') });
return [{ json: { ...base, policy: { allowed: blocked.length === 0, blocked, enrolled_today: enrolledToday, remaining_before_request: remaining, checked_at: new Date().toISOString() } } }];

const data = $input.first().json;
const leads = data.contacts.map(contact => ({
  email: contact.email,
  first_name: contact.first_name || undefined,
  last_name: contact.last_name || undefined,
  company_name: contact.company_name || undefined,
  job_title: contact.job_title || undefined,
  website: contact.website || undefined,
  phone: contact.phone || undefined,
  personalization: contact.personalization || undefined,
  custom_variables: { source: 'javedai_n8n', request_id: data.request_id, contact_key: contact.contact_key, lawful_basis: contact.lawful_basis }
}));
return [{ json: { ...data, instantly_request: { leads, campaign_id: data.campaign_id, verify_leads_on_import: false, skip_if_in_workspace: true } } }];

const base = $node['Prepare Instantly v2 Request'].json;
const api = $input.first().json || {};
const accepted = Number(api.leads_uploaded ?? api.created ?? 0);
return [{ json: {
  status: api.status === 'success' ? 'enrolled' : 'submitted',
  request_id: base.request_id,
  campaign_id: base.campaign_id,
  requested_count: base.contacts.length,
  accepted_count: Number.isFinite(accepted) ? accepted : 0,
  total_sent: Number(api.total_sent ?? base.contacts.length),
  contact_keys: base.contacts.map(c => c.contact_key),
  idempotency_keys: base.contacts.map(c => c.idempotency_key),
  policy_checked_at: base.policy.checked_at,
  completed_at: new Date().toISOString(),
  provider_status: String(api.status || 'unknown')
} }];
